/bin/bash -lc "python - <<'PY'
import cv2,numpy as np
im=cv2.imread('first_frame.png')[:,:,::-1]
# print connected components thresholds with bboxes
for name,m in [('bright',(im.mean(2)>190).astype('uint8')),('blue',((im[:,:,2]>im[:,:,0]*1.15)&(im[:,:,2]>im[:,:,1]*1.1)&(im[:,:,2]>120)).astype('uint8')),('dark',(im.mean(2)<45).astype('uint8'))]:
 print('\\n',name)
 n,l,st,cent=cv2.connectedComponentsWithStats(m,8)
 for x,y,w,h,a in sorted(st[1:],key=lambda v:-v[4])[:20]: print(x,y,w,h,a)
# Bright per-row intervals >180 mean, groups >=3
m=im.mean(2)>185
print('bright intervals')
for y in range(0,180,4):
 z=m[y:y+4].any(0); runs=[]; on=False
 for x,v in enumerate(np.r_[z,False]):
  if v and not on:s=x;on=True
  if not v and on:
   if x-s>=3:runs.append((s,x-1))
   on=False
 print(y,runs)
PY"
